 const [view,setView]=useState<View>('home');const [items,setItems]=useState<Incident[]>(demoIncidents);const [selected,setSelected]=useState<string|null>(null);const [notice,setNotice]=useState('');const [error,setError]=useState('');const [menu,setMenu]=useState(false);const [query,setQuery]=useState('');const [typeFilter,setTypeFilter]=useState('All types');const [statusFilter,setStatusFilter]=useState('All statuses');const [priorityFilter,setPriorityFilter]=useState('All priorities');const [sort,setSort]=useState('Newest first');const [source,setSource]=useState('All incidents');const [storage,setStorage]=useState<'loading'|'connected'|'unavailable'>('loading');const [saving,setSaving]=useState(false);const [receipt,setReceipt]=useState<Incident|null>(null);const [tab,setTab]=useState('Overview');const [notifications,setNotifications]=useState(false);const [crew,setCrew]=useState('Vehicle Crew 1');const [routeIds,setRouteIds]=useState<string[]>([]);const [suggested,setSuggested]=useState(false);const [dateRange,setDateRange]=useState('Last 7 days');const [routeDay,setRouteDay]=useState('Today');const [includeDemo,setIncludeDemo]=useState(true);
 const [plans,setPlans]=useState<RoutePlan[]>([]);const [merges,setMerges]=useState<{id:string;sourceId:string;targetId:string;createdAt:string}[]>([]);const [authority,setAuthority]=useState('');const [mergeTarget,setMergeTarget]=useState('');
 const [step,setStep]=useState(1);const [photo,setPhoto]=useState<File|null>(null);const [photoPreview,setPhotoPreview]=useState('');const [loc,setLoc]=useState({lat:51.5134,lng:-.3056});const [address,setAddress]=useState('');const [locationConfirmed,setLocationConfirmed]=useState(false);const [note,setNote]=useState('');const [category,setCategory]=useState('Other');const [hazardConcern,setHazardConcern]=useState<HazardConcern>('no');const [gps,setGps]=useState('');const [lookup,setLookup]=useState('');const [submissionId,setSubmissionId]=useState('');const [receiptLookup,setReceiptLookup]=useState('');
 const [language,setLanguage]=useState<ReportLanguage>('en');const [phoneDemo,setPhoneDemo]=useState(false);const [phoneStarted,setPhoneStarted]=useState(false);const [phoneLocation,setPhoneLocation]=useState('');const [phoneIssue,setPhoneIssue]=useState('');
 const photoInput=useRef<HTMLInputElement>(null);const galleryInput=useRef<HTMLInputElement>(null);const afterInput=useRef<HTMLInputElement>(null);
