 useEffect(()=>{setView(fromPath());const pop=()=>{setView(fromPath());setSelected(null)};window.addEventListener('popstate',pop);setSubmissionId(makeId());setIncludeDemo(localStorage.getItem('wasteops-examples')!=='hidden');load();return()=>window.removeEventListener('popstate',pop)},[]);
 useEffect(()=>{if(!photo)return;const u=URL.createObjectURL(photo);setPhotoPreview(u);return()=>URL.revokeObjectURL(u)},[photo]);
