 async function lookupReport(value:string,open=false){const reference=value.trim().toUpperCase();if(!reference){setError('Enter your report reference.');return}setSaving(true);setError('');try{const r=await fetch(`/api/report-status?reference=${encodeURIComponent(reference)}`);const j=await r.json() as TrackedReport&{error?:string};if(!r.ok)throw new Error(j.error||'We could not find that report. Check the reference and try again.');setReceipt(fromTracking(j));if(open){setView('status');window.history.pushState({},'',`/report/status/${encodeURIComponent(j.reference)}`)}}catch(e){setError((e as Error).message)}finally{setSaving(false)}}
 async function load(){const trackingKey=decodeURIComponent(window.location.pathname.split('/report/status/')[1]||'');if(/^WO-\d{4}-[A-F0-9]{16}$/i.test(trackingKey))void lookupReport(trackingKey);try{const r=await fetch('/api/incidents');if(!r.ok)throw new Error();const j=await r.json() as {incidents:Incident[]};setItems([...j.incidents,...demoIncidents.filter(d=>!j.incidents.some((i:Incident)=>i.id===d.id))]);setStorage('connected');const [pr,mr]=await Promise.all([fetch('/api/routes'),fetch('/api/merges')]);if(pr.ok)setPlans(((await pr.json()) as {plans:RoutePlan[]}).plans);if(mr.ok)setMerges(((await mr.json()) as {merges:{id:string;sourceId:string;targetId:string;createdAt:string}[]}).merges);if(trackingKey&&!trackingKey.startsWith('WO-')){const i=j.incidents.find((x:Incident)=>x.token===trackingKey);if(i)setReceipt(i)}}catch{setStorage('unavailable')}}
 useEffect(()=>{if(!selected)return;const previous=document.activeElement as HTMLElement|null;const panel=document.querySelector('.detail-panel');const focusable=()=>Array.from(panel?.querySelectorAll<HTMLElement>('button:not(:disabled), a[href], select:not(:disabled), input:not([hidden]), textarea')||[]).filter(x=>x.offsetParent!==null);focusable()[0]?.focus();const trap=(e:KeyboardEvent)=>{if(e.key!=='Tab')return;const all=focusable();if(!all.length)return;const first=all[0],last=all[all.length-1];if(e.shiftKey&&(document.activeElement===first||!panel?.contains(document.activeElement))){e.preventDefault();last.focus()}else if(!e.shiftKey&&(document.activeElement===last||!panel?.contains(document.activeElement))){e.preventDefault();first.focus()}};document.addEventListener('keydown',trap);return()=>{document.removeEventListener('keydown',trap);previous?.focus()}},[selected]);
 const active=items.find(i=>i.id===selected);const visible=items.filter(i=>!i.mergedInto).filter(i=>includeDemo||!i.demo).filter(i=>source!=='My reports'||!i.demo).filter(i=>(typeFilter==='All types'||i.category===typeFilter)&&(statusFilter==='All statuses'||i.status===statusFilter)&&(priorityFilter==='All priorities'||incidentPriority(i)===priorityFilter)&&`${i.address} ${i.reference} ${i.category} ${incidentPriority(i)}`.toLowerCase().includes(query.toLowerCase())).sort((a,b)=>sort==='Oldest first'?a.createdAt.localeCompare(b.createdAt):sort==='Priority first'?['Urgent','High','Standard','Low'].indexOf(incidentPriority(a))-['Urgent','High','Standard','Low'].indexOf(incidentPriority(b)):b.createdAt.localeCompare(a.createdAt));
 const displayed=items.filter(i=>!i.mergedInto).filter(i=>includeDemo||!i.demo);const dates=displayed.length?Math.max(...displayed.map(i=>new Date(i.createdAt).getTime())):Date.now();const days=dateRange==='Last 7 days'?7:dateRange==='Last 30 days'?30:365;const stats=displayed.filter(i=>new Date(i.createdAt).getTime()>=dates-days*86400000);const count=(s:string)=>stats.filter(i=>i.status===s).length;
 const open=(i:Incident)=>{setSelected(i.id);setTab('Overview');setAuthority('');setMergeTarget('');setError('')};
 async function update(i:Incident,body:Record<string,unknown>){setSaving(true);setError('');try{const r=await fetch('/api/incidents',{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({id:i.id,...body})});const j=await r.json() as {incident:Incident;error?:string};if(!r.ok)throw new Error(j.error||'Could not save changes.');setItems(x=>x.map(a=>a.id===i.id?j.incident:a));if(receipt?.id===i.id)setReceipt(j.incident);toast('Changes saved');}catch(e){setError((e as Error).message)}finally{setSaving(false)}}
 async function upload(file:File){const form=new FormData();form.set('photo',file);const r=await fetch('/api/uploads',{method:'POST',body:form});const j=await r.json() as {key:string;error?:string};if(!r.ok)throw new Error(j.error||'Upload failed.');return j.key as string;}
 async function submit(){if(!photo||!locationConfirmed)return;setSaving(true);setError('');try{const image=new Image();image.src=photoPreview;await image.decode();const canvas=document.createElement('canvas');const scale=Math.min(1,1600/Math.max(image.naturalWidth,image.naturalHeight));canvas.width=image.naturalWidth*scale;canvas.height=image.naturalHeight*scale;canvas.getContext('2d')!.drawImage(image,0,0,canvas.width,canvas.height);const blob=await new Promise<Blob|null>(r=>canvas.toBlob(r,'image/jpeg',.86));if(!blob)throw new Error('Could not process the photo. Please choose another.');const key=await upload(new File([blob],'report.jpg',{type:'image/jpeg'}));const r=await fetch('/api/incidents',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...loc,address,note,category,hazardConcern,photoKey:key,submissionId})});const j=await r.json() as {incident:Incident;error?:string};if(!r.ok)throw new Error(j.error||'Your report was not submitted. Please retry.');setReceipt(j.incident);setItems(a=>[j.incident,...a.filter(x=>x.id!==j.incident.id)]);navigate('receipt');}catch(e){setError((e as Error).message)}finally{setSaving(false)}}
 function choosePhoto(file?:File){if(!file)return;if(file.size>10000000||!['image/jpeg','image/png','image/webp'].includes(file.type)){setError('Choose a JPG, PNG or WebP photo smaller than 10 MB.');return}setPhoto(file);setError('')}
 function getLocation(){if(!navigator.geolocation){setGps(copy.locUnavailable);return}setGps(copy.locFinding);navigator.geolocation.getCurrentPosition(p=>{setLoc({lat:p.coords.latitude,lng:p.coords.longitude});setLocationConfirmed(false);setAddress(`Near ${p.coords.latitude.toFixed(5)}, ${p.coords.longitude.toFixed(5)}`);setGps(copy.locFound);},()=>setGps(copy.locAccessUnavailable),{enableHighAccuracy:true,timeout:10000})}
 async function findAddress(){if(address.trim().length<3){setGps(copy.addressRequired);return}setGps(copy.addressFinding);try{const r=await fetch(`https://nominatim.openstreetmap.org/search?format=json&limit=1&countrycodes=gb&q=${encodeURIComponent(address)}`);if(!r.ok)throw new Error();const j=await r.json() as {lat:string;lon:string;display_name:string}[];if(!j[0])throw new Error();setLoc({lat:Number(j[0].lat),lng:Number(j[0].lon)});setAddress(j[0].display_name.split(',').slice(0,4).join(','));setLocationConfirmed(false);setGps(copy.addressFound)}catch{setGps(copy.addressUnavailable)}}
 function resetReport(){setReceipt(null);setPhoto(null);setPhotoPreview('');setStep(1);setNote('');setCategory('Other');setHazardConcern('no');setLocationConfirmed(false);setAddress('');setSubmissionId(makeId());navigate('report')}
 const reportButton=(label='Report an issue')=><button className="btn primary" onClick={resetReport}>{label}<ArrowRight size={16}/></button>;
 function exportCsv(){const rows=[['Reference','Category','Priority','Safety flag','Status','Location','Crew','Reported'],...visible.map(i=>[i.reference,i.category,incidentPriority(i),i.hazardConcern||'',i.status,i.address,i.crew,i.createdAt])];const csv=rows.map(r=>r.map(v=>'"'+v.replaceAll('"','""').replace(/^[=+@-]/,"'$&")+'"').join(',')).join('\n');const u=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));const a=document.createElement('a');a.href=u;a.download='wasteops-incidents.csv';a.click();URL.revokeObjectURL(u);toast('Incident export downloaded')}
