 const filters=<div className="filters"><div className="filter-pair"><select aria-label="Incident type" value={typeFilter} onChange={e=>setTypeFilter(e.target.value)}><option>All types</option>{categories.map(x=><option key={x}>{x}</option>)}</select><select aria-label="Incident status" value={statusFilter} onChange={e=>setStatusFilter(e.target.value)}><option>All statuses</option>{statuses.map(x=><option key={x}>{x}</option>)}</select><select aria-label="Incident priority" value={priorityFilter} onChange={e=>setPriorityFilter(e.target.value)}><option>All priorities</option>{priorities.map(x=><option key={x}>{x}</option>)}</select></div><select aria-label="Sort incidents" value={sort} onChange={e=>setSort(e.target.value)}><option>Newest first</option><option>Oldest first</option><option>Priority first</option></select></div>;
 const row=(i:Incident)=><button key={i.id} className={`incident-row ${selected===i.id?'is-selected':''}`} onClick={()=>open(i)}><SmallPhoto i={i}/><span className="row-copy"><strong>{i.reference}</strong><span>{i.category}</span><small>{i.address}</small></span><span className="row-end"><PriorityBadge priority={incidentPriority(i)}/><Badge status={i.status}/><small>{fmt(i.createdAt)}</small></span></button>;
 const empty=<div className="empty"><Inbox size={35}/><h3>No incidents to show</h3><p>Try changing your filters or report a local issue.</p><button className="btn" onClick={()=>{setQuery('');setTypeFilter('All types');setStatusFilter('All statuses');setPriorityFilter('All priorities');setSource('All incidents')}}>Clear filters</button></div>;
 const completedRecords=stats.filter(i=>i.job?.status==='Accepted');const resolutionHours=completedRecords.map(i=>{const accepted=[...i.job!.events].reverse().find(e=>e.text.includes('accepted'));return accepted?Math.max(0,(new Date(accepted.at).getTime()-new Date(i.createdAt).getTime())/3600000):null}).filter((h):h is number=>h!==null);const averageResolution=resolutionHours.length?resolutionHours.reduce((a,b)=>a+b,0)/resolutionHours.length:null;
 const cards=<div className="stats-grid">{[{label:'Total incidents',value:stats.length,icon:ClipboardList},{label:'Resolved',value:count('Resolved'),icon:CheckCircle2},{label:'In progress',value:count('In progress'),icon:Activity},{label:'Unassigned',value:stats.filter(i=>!i.crew&&i.status!=='Resolved').length,icon:Users}].map((s,j)=><div className="stat-card" key={s.label}><div className="stat-top"><span>{s.label}</span><s.icon size={16}/></div><div className="stat-bottom"><strong>{s.value}</strong><Spark values={Array.from({length:7},(_,n)=>{const day=new Date(dates-(6-n)*86400000).toISOString().slice(0,10);return stats.filter(i=>i.createdAt.startsWith(day)&&(j===0||j===1&&i.status==='Resolved'||j===2&&i.status==='In progress'||j===3&&!i.crew&&i.status!=='Resolved')).length})}/></div><small>{includeDemo?'Includes illustrative demo incidents':'Your saved reports'}</small></div>)}</div>;
